import {
  Mjml,
  MjmlBody,
  MjmlColumn,
  MjmlFont,
  MjmlHead,
  MjmlPreview,
  MjmlSection,
  MjmlSpacer,
  MjmlText,
  MjmlWrapper,
} from "@faire/mjml-react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type RollingStats_RollingStatsVariant =
  | "centered"
  | "top-left"
  | "bottom-left"
  | "top-right"
  | "bottom-right";

interface RollingStats_RollingStatsProps {
  theme?: EmailTheme;
  variant?: RollingStats_RollingStatsVariant;
  eyebrow?: string;
  label?: string;
  values?: [string, string, string];
  pageBackgroundColor?: string;
  backgroundColor?: string;
  panelBackgroundColor?: string;
  eyebrowColor?: string;
  labelColor?: string;
  firstValueColor?: string;
  secondValueColor?: string;
  accentColor?: string;
}

const RollingStats_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const RollingStats_accentColors: Record<
  RollingStats_RollingStatsVariant,
  string
> = {
  "bottom-left": "#c7d2fe",
  "bottom-right": "#a7f3d0",
  centered: "#e9d5ff",
  "top-left": "#fde68a",
  "top-right": "#fecdd3",
};

const RollingStats_RollingStatsSection = ({
  accentColor,
  backgroundColor = "#fffffe",
  eyebrow = "Mapped trails",
  eyebrowColor = "#9ca3af",
  firstValueColor = "#262626",
  label = "Tracked by active users",
  labelColor = "#fffffe",
  panelBackgroundColor = "#030712",
  secondValueColor = "#737373",
  values,
  variant = "centered",
}: Omit<RollingStats_RollingStatsProps, "theme">) => {
  const centered = variant === "centered";
  const bottom = variant.startsWith("bottom-");
  let align: "center" | "left" | "right" = "left";
  if (centered) {
    align = "center";
  } else if (variant.endsWith("-right")) {
    align = "right";
  }
  let topSpacer = "24px";
  let bottomSpacer = "92px";
  if (centered) {
    topSpacer = "58px";
    bottomSpacer = "58px";
  } else if (bottom) {
    topSpacer = "92px";
    bottomSpacer = "24px";
  }
  const resolvedValues =
    values ??
    (centered
      ? (["3,117km", "3,118km", "3,119km"] as const)
      : (["14,598", "14,599", "14,600"] as const));
  return (
    <MjmlSection backgroundColor={backgroundColor} padding="44px 24px">
      <MjmlColumn
        backgroundColor={panelBackgroundColor}
        borderRadius="8px"
        padding="0 24px"
      >
        <MjmlSpacer height={topSpacer} />
        <MjmlText
          align={align}
          color={eyebrowColor}
          fontFamily={RollingStats_fontFamily}
          fontSize="14px"
          fontWeight="600"
          lineHeight="20px"
          padding="0"
          textTransform="uppercase"
        >
          {eyebrow}
        </MjmlText>
        {[
          firstValueColor,
          secondValueColor,
          accentColor ?? RollingStats_accentColors[variant],
        ].map((color, index) => (
          <MjmlText
            align={align}
            color={color}
            fontFamily={RollingStats_fontFamily}
            fontSize="72px"
            fontWeight="500"
            key={`${resolvedValues[index]}-${index}`}
            lineHeight="56px"
            padding={index === 0 ? "12px 0 0" : "0"}
          >
            {resolvedValues[index]}
          </MjmlText>
        ))}
        <MjmlText
          align={align}
          color={labelColor}
          fontFamily={RollingStats_fontFamily}
          fontSize="16px"
          lineHeight="24px"
          padding="16px 0 0"
        >
          {label}
        </MjmlText>
        <MjmlSpacer height={bottomSpacer} />
      </MjmlColumn>
    </MjmlSection>
  );
};

const RollingStats_RollingStats = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  ...props
}: RollingStats_RollingStatsProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>Rolling activity statistics</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody
      backgroundColor={pageBackgroundColor}
      width={theme.containerWidth}
    >
      <MjmlWrapper padding="0">
        <RollingStats_RollingStatsSection {...props} />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

RollingStats_RollingStats.PreviewProps = {
  theme: defaultTheme,
  variant: "centered",
} satisfies RollingStats_RollingStatsProps;

const __RollingStats = RollingStats_RollingStats;

type SingleStat_SingleStatWithBackgroundImageVariant =
  | "centered"
  | "top-left"
  | "bottom-left"
  | "top-right"
  | "bottom-right";

interface SingleStat_SingleStatWithBackgroundImageProps {
  theme?: EmailTheme;
  variant?: SingleStat_SingleStatWithBackgroundImageVariant;
  eyebrow?: string;
  label?: string;
  value?: string;
  backgroundImageSrc?: string;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  overlayColor?: string;
  eyebrowColor?: string;
  labelColor?: string;
  valueColor?: string;
}

const SingleStat_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const SingleStat_valueColors: Record<
  SingleStat_SingleStatWithBackgroundImageVariant,
  string
> = {
  "bottom-left": "#c7d2fe",
  "bottom-right": "#a7f3d0",
  centered: "#e9d5ff",
  "top-left": "#fde68a",
  "top-right": "#fecdd3",
};

const SingleStat_SingleStatWithBackgroundImageSection = ({
  backgroundImageSrc = emailAsset("stats/single-stat.jpg"),
  eyebrow = "Mapped trails",
  eyebrowColor = "#d1d5db",
  label = "Tracked by active users",
  labelColor = "#fffffe",
  value = "3,120km",
  valueColor,
  variant = "centered",
}: Omit<SingleStat_SingleStatWithBackgroundImageProps, "theme">) => {
  const centered = variant === "centered";
  const bottom = variant.startsWith("bottom-");
  let align: "center" | "left" | "right" = "left";
  if (centered) {
    align = "center";
  } else if (variant.endsWith("-right")) {
    align = "right";
  }
  let topSpacer = "24px";
  let bottomSpacer = "185px";
  if (centered) {
    topSpacer = "104px";
    bottomSpacer = "104px";
  } else if (bottom) {
    topSpacer = "185px";
    bottomSpacer = "24px";
  }
  return (
    <MjmlSection
      backgroundColor="#000001"
      backgroundPosition="center"
      backgroundRepeat="no-repeat"
      backgroundSize="cover"
      backgroundUrl={backgroundImageSrc}
      borderRadius="8px"
      padding="0 24px"
    >
      <MjmlColumn padding="0">
        <MjmlSpacer height={topSpacer} />
        <MjmlText
          align={align}
          color={eyebrowColor}
          fontFamily={SingleStat_fontFamily}
          fontSize="14px"
          fontWeight="600"
          lineHeight="20px"
          padding="0"
          textTransform="uppercase"
        >
          {eyebrow}
        </MjmlText>
        <MjmlText
          align={align}
          color={valueColor ?? SingleStat_valueColors[variant]}
          fontFamily={SingleStat_fontFamily}
          fontSize="72px"
          fontWeight="500"
          lineHeight="80px"
          padding="12px 0 0"
        >
          {value}
        </MjmlText>
        <MjmlText
          align={align}
          color={labelColor}
          fontFamily={SingleStat_fontFamily}
          fontSize="16px"
          lineHeight="24px"
          padding="16px 0 0"
        >
          {label}
        </MjmlText>
        <MjmlSpacer height={bottomSpacer} />
      </MjmlColumn>
    </MjmlSection>
  );
};

const SingleStat_SingleStatWithBackgroundImage = ({
  backgroundColor = "#fffffe",
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  ...props
}: SingleStat_SingleStatWithBackgroundImageProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>Single activity statistic</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody
      backgroundColor={pageBackgroundColor}
      width={theme.containerWidth}
    >
      <MjmlWrapper backgroundColor={backgroundColor} padding="44px 24px">
        <SingleStat_SingleStatWithBackgroundImageSection {...props} />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

SingleStat_SingleStatWithBackgroundImage.PreviewProps = {
  theme: defaultTheme,
  variant: "centered",
} satisfies SingleStat_SingleStatWithBackgroundImageProps;

const __SingleStat = SingleStat_SingleStatWithBackgroundImage;

export interface SpotlightStatsProps {
  theme?: Parameters<typeof __RollingStats>[0]["theme"];
  eyebrow?: string;
  label?: string;
  values?: string[];
  position?:
    | "center"
    | "top-left"
    | "top-right"
    | "bottom-left"
    | "bottom-right";
  backgroundImage?: {
    src: string;
    alt?: string;
  };
}

const spotlightStatsDefinedProps = <Props extends object>(props: Props) =>
  Object.fromEntries(
    Object.entries(props).filter(([, value]) => value !== undefined)
  ) as Partial<Props>;

export const SpotlightStats = ({
  theme,
  eyebrow,
  label,
  values,
  position = "center",
  backgroundImage,
}: SpotlightStatsProps) => {
  const variant = position === "center" ? "centered" : position;
  const contentProps = spotlightStatsDefinedProps({ eyebrow, label, theme });
  if (backgroundImage) {
    return (
      <__SingleStat
        backgroundImageSrc={backgroundImage.src}
        variant={variant}
        {...contentProps}
        {...spotlightStatsDefinedProps({ value: values?.[0] })}
      />
    );
  }
  return (
    <__RollingStats
      variant={variant}
      {...contentProps}
      {...spotlightStatsDefinedProps({
        values:
          values && values.length >= 3
            ? [values[0], values[1], values[2]]
            : undefined,
      })}
    />
  );
};

SpotlightStats.PreviewProps = {
  position: "center",
} satisfies SpotlightStatsProps;

const ASSET_ORIGIN = "https://www.emailcn.run";
const ICONS8_ORIGIN = "https://img.icons8.com";
const UNSPLASH_ORIGIN = "https://images.unsplash.com";

const portraitIds = [
  "photo-1500648767791-00dcc994a43e",
  "photo-1507003211169-0a1dd7228f2d",
  "photo-1494790108377-be9c29b29330",
  "photo-1438761681033-6461ffad8d80",
  "photo-1534528741775-53994a69daeb",
  "photo-1506794778202-cad84cf45f1c",
] as const;

const productIds = [
  "photo-1521572163474-6864f9cf17ab",
  "photo-1503341504253-dff4815485f1",
  "photo-1576566588028-4147f3842f27",
  "photo-1562157873-818bc0726f68",
] as const;

const socialIconSlugs = {
  discord: "discord-logo",
  facebook: "facebook-new",
  github: "github",
  instagram: "instagram-new",
  linkedin: "linkedin",
  slack: "slack-new",
  x: "twitterx--v1",
  youtube: "youtube-play",
} as const;

const brandIconSlugs = [
  [/(?:btc|bitcoin)/i, "bitcoin--v1"],
  [/(?:eth|ethereum)/i, "ethereum"],
  [/visa/i, "visa"],
  [/mastercard/i, "mastercard-logo"],
  [/apple-pay/i, "apple-pay"],
  [/google-pay/i, "google-pay"],
  [/klarna/i, "klarna"],
  [/stripe/i, "stripe"],
  [/fedex/i, "fedex"],
  [/north-face/i, "the-north-face"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/teams\/member-\d+-lg/i.test(path)) {
    return [800, 560] as const;
  }
  if (/teams\/member-\d+/i.test(path)) {
    return [600, 600] as const;
  }
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

const getIndexedAsset = (path: string, assets: readonly string[]) => {
  const explicitIndex = path.match(
    /(?:member|avatar|product-list|shopping-cart)-(\d+)/i
  )?.[1];
  const index = explicitIndex
    ? Number.parseInt(explicitIndex, 10) - 1
    : hashString(path);

  return assets[((index % assets.length) + assets.length) % assets.length];
};

const getUnsplashAsset = (id: string, width: number, height: number) =>
  `${UNSPLASH_ORIGIN}/${id}?auto=format&fit=crop&w=${width}&h=${height}&q=80`;

const getIcons8Asset = (
  slug: string,
  {
    color,
    style = "ios-filled",
  }: {
    color?: string;
    style?: "color" | "ios" | "ios-filled";
  } = {}
) =>
  color
    ? `${ICONS8_ORIGIN}/${style}/50/${color}/${slug}.png`
    : `${ICONS8_ORIGIN}/${style}/50/${slug}.png`;

const getStoreBadgeAsset = (path: string) => {
  if (/badge-app-store/i.test(path)) {
    return "https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg";
  }
  if (/badge-google-play/i.test(path)) {
    return "https://play.google.com/intl/en_us/badges/static/images/badges/en_badge_web_generic.png";
  }
};

const getSocialIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  for (const [name, slug] of Object.entries(socialIconSlugs)) {
    if (new RegExp(`(?:^|[-/])${name}(?:[-.]|$)`, "i").test(path)) {
      return getIcons8Asset(slug, { color: foreground });
    }
  }
};

const getUtilityIconAsset = (path: string) => {
  const isLight = /(?:-light|check-white)/i.test(path);
  const foreground = isLight ? "FFFFFF" : "111827";

  if (/star-half/i.test(path)) {
    return getIcons8Asset("star-half-empty", { color: "374151" });
  }
  if (/star-solid/i.test(path)) {
    return getIcons8Asset("star--v1", { color: "374151" });
  }
  if (/edit/i.test(path)) {
    return getIcons8Asset("edit--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/arrow-right/i.test(path)) {
    return getIcons8Asset("long-arrow-right--v1", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/chevron-right/i.test(path)) {
    return getIcons8Asset("chevron-right", {
      color: "4F46E5",
      style: "ios",
    });
  }
  if (/check/i.test(path)) {
    return getIcons8Asset("checkmark--v1", { color: foreground });
  }
};

const getBrandIconAsset = (path: string) => {
  const match = brandIconSlugs.find(([pattern]) => pattern.test(path));

  return match
    ? getIcons8Asset(match[1], {
        style: "color",
      })
    : undefined;
};

const getWordmarkAsset = (path: string) => {
  const isLight = /light/i.test(path);
  const background = isLight ? "030712" : "FFFFFF";
  const foreground = isLight ? "FFFFFF" : "111827";

  return `https://placehold.co/320x96/${background}/${foreground}.png?text=EMAILCN`;
};

const getIconAsset = (path: string) =>
  getStoreBadgeAsset(path) ??
  getSocialIconAsset(path) ??
  getUtilityIconAsset(path) ??
  getBrandIconAsset(path);

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const iconAsset = getIconAsset(normalizedPath);
  if (iconAsset) {
    return iconAsset;
  }

  const seed = getSeed(normalizedPath);
  const [width, height] = getDimensions(normalizedPath);

  if (/teams\/hero/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1521737711867-e3b97375f902", width, height);
  }

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, portraitIds),
      width,
      height
    );
  }

  if (/products\/shoe/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1542291026-7eec264c27ff", width, height);
  }

  if (/products\/phone/i.test(normalizedPath)) {
    return getUnsplashAsset("photo-1511707171634-5f897ff02aa9", width, height);
  }

  if (
    /(?:product-detail|product-lists|products\/product|shopping-cart)/i.test(
      normalizedPath
    )
  ) {
    return getUnsplashAsset(
      getIndexedAsset(normalizedPath, productIds),
      width,
      height
    );
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (/(?:emailcn|maizzle|logo|insignia)/i.test(normalizedPath)) {
    return getWordmarkAsset(normalizedPath);
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
